        r = c.rack
        b = r.block
        bc = K.building(b.building.warehouse.code, b.building.number)
        c.code, c.row, c.floor = K.cell(K.rack(K.block(bc, b.code), r.number), q, f), q, f
        c.save(update_fields=["code", "row", "floor"])


